declare(strict_types=1);
if(PHP_SAPI!=='cli'){fwrite(STDERR,"Partners tests are CLI-only.\n");exit(1);} $root=dirname(__DIR__);
spl_autoload_register(static function(string$class)use($root):void{$p='Babanoell\\Partners\\';if(!str_starts_with($class,$p))return;$f=$root.'/src/'.str_replace('\\','/',substr($class,strlen($p))).'.php';if(is_file($f))require$f;});
$tests=[];$add=static function(string$n,callable$f)use(&$tests){$tests[$n]=$f;};$assert=static function(bool$v,string$m='assertion failed'){if(!$v)throw new RuntimeException($m);};$eq=static function(mixed$a,mixed$b){if($a!==$b)throw new RuntimeException(var_export($a,true).' !== '.var_export($b,true));};

$add('release metadata identifies partners and supported capabilities',function()use($root,$assert,$eq){$v=require$root.'/config/version.php';$eq('partners',$v['service']);$assert(preg_match('/^\d+\.\d+\.\d+$/D',$v['version'])===1);$assert(version_compare($v['version'],'1.6.0','>='));$assert(is_string($v['phase'])&&trim($v['phase'])!=='');});
