$add('batch 2 revision rejects invalid reason before changing the database',function()use($assert){
 $pdo=(new ReflectionClass(PDO::class))->newInstanceWithoutConstructor();
 $svc=new Babanoell\Partners\Contract\ContractRevisionService($pdo,new Babanoell\Partners\Contract\ContractRepository($pdo));
 foreach([['reason'=>'short','row_version'=>2],['reason'=>'توضیح کامل بازصدور','row_version'=>0],['reason'=>'reason of reissue valid','row_version'=>1,'mode'=>'invalid']]as$bad){
  $thrown=false;try{$svc->reissue(str_repeat('a',26),str_repeat('b',26),$bad);}catch(InvalidArgumentException){$thrown=true;}$assert($thrown,'invalid payload must fail closed');
 }
});
$add('batch 2 printable contract includes immutable hash and secure rendering controls',function()use($assert){
 $record=['contract_no'=>'NOEL-2','status'=>'signed','rendered_content'=>'<p>قرارداد تسهیلات</p>','revision'=>2,'mode'=>'digital','rendered_hash'=>str_repeat('a',64),'signed_at'=>'2026-10-21 12:00:00'];
 $page=Babanoell\Partners\Contract\ContractPrintView::render($record,true,'token',false);
 foreach(['@page','A4','NOEL-2','گواهی ثبت وضعیت قرارداد',str_repeat('a',64),'نسخه 2']as$snippet)$assert(str_contains($page,$snippet),$snippet);
 $assert(!str_contains($page,'otp/request'));
 $dev=Babanoell\Partners\Contract\ContractPrintView::render(['status'=>'pending','mode'=>'digital'],false,'test-token',true);
 $prod=Babanoell\Partners\Contract\ContractPrintView::render(['status'=>'pending','mode'=>'digital'],false,'test-token',false);
 $assert(str_contains($dev,'otp/request'));$assert(!str_contains($prod,'otp/request'));$enabled=Babanoell\Partners\Contract\ContractPrintView::render(['status'=>'pending','mode'=>'digital'],false,'test-token',true);$assert(str_contains($enabled,'otp/request'));
});
$add('batch 2 contract routes require management access for reissue and no mock OTP in production',function()use($root,$assert){
 $index=file_get_contents($root.'/public/index.php');$service=file_get_contents($root.'/src/Contract/ContractService.php');
 foreach(['/reissue','$canManageContract','$contractRevisionService','/print','ContractPrintView']as$x)$assert(str_contains($index,$x),$x);
 $assert(str_contains($service,'if(!$this->production)'));$assert(str_contains($service,'invalidateOtp'));$assert(str_contains($service,'sendContractOtp'));
 $assert(str_contains($service,'signer')); // original signer snapshot is preserved
});

